S=Path(__file__).resolve().parent;C=S/'candidate03';T=C/'textures';T.mkdir(exist_ok=True);D=json.loads((C/'design.json').read_text());F=json.loads((C/'asset_fit.json').read_text());raw=Image.open(C/'wood_imagegen.png').convert('RGB');bounds=D['bounds'];bw=bounds['xmax']-bounds['xmin'];bh=bounds['ymax']-bounds['ymin'];ratio=bw/bh;box=F['core_bbox'];cx=(box[0]+box[2])/2;cy=(box[1]+box[3])/2;kw=box[2]-box[0];kh=box[3]-box[1];assert kw>0 and kh>0
