W=D['texture_width'];H=D['texture_height'];pad=D['padding'];w=W-2*pad;h=H-2*pad;im=raw.transform((w,h),Image.Transform.EXTENT,rect,Image.Resampling.BICUBIC);rgb=np.asarray(im,dtype=float)/255
lin=np.where(rgb<=.04045,rgb/12.92,((rgb+.055)/1.055)**2.4);Y=lin@np.array([.2126,.7152,.0722]);log=np.log(np.maximum(Y,.0001));broad=gaussian_filter(log,(h*.11,w*.07));gain=np.exp(np.clip(np.median(broad)-broad,-.30,.30)*D.get('illumination_flatten_strength',.85));lin*=gain[:,:,None];lum=lin@np.array([.2126,.7152,.0722]);lin*=D.get('target_luminance',.10)/(np.median(lum)+1e-8);lin=np.clip(lin,0,.95);rgb=np.where(lin<=.0031308,lin*12.92,1.055*lin**(1/2.4)-.055)
dx=bw/(w-1);dy=bh/(h-1);L=np.log(np.maximum(lin@np.array([.2126,.7152,.0722]),.0001));local=gaussian_filter(L,(.035/dy,.13/dx));cavity=np.clip((local-L-.04)/.85,0,1);cavity=gaussian_filter(cavity,(.003/dy,.004/dx));detail=L-gaussian_filter(L,(.012/dy,.025/dx));height=-.0045*cavity+.0003*np.clip(detail,-1,1);height=gaussian_filter(height,(.002/dy,.002/dx));gy,gx=np.gradient(height,dy,dx);gy=-gy;N=np.stack([-gx,-gy,np.ones_like(gx)],2);sl=np.linalg.norm(N[:,:,:2],axis=2);fac=np.minimum(1,np.tan(np.deg2rad(20))/(sl+1e-12));N[:,:,:2]*=fac[:,:,None];N/=np.linalg.norm(N,axis=2)[:,:,None];normal=.5+.5*N;rough=np.clip(.74+.08*cavity+.012*np.tanh(local-L),.68,.85)
def save(name,a):
 pads=((pad,pad),(pad,pad),(0,0)) if a.ndim==3 else ((pad,pad),(pad,pad));a=np.pad(a,pads,mode='edge');Image.fromarray(np.uint8(np.clip(a,0,1)*255+.5)).save(T/name)
